-- ************************************** POS.DIM_CUSTOMER
CREATE TABLE IF NOT EXISTS POS.DIM_CUSTOMER
(
 CUSTOMER_ID  number NOT NULL COMMENT 'A unique identifier for each customer.',
 FROM_DTS     timestamp_ntz(9) NOT NULL,
 TO_DTS       timestamp_ntz(9) NOT NULL,
 F_NAME       varchar2(50) COMMENT 'The first name of the customer',
 LAST_NAME    varchar2(50) COMMENT 'The last name of the customer.',
 EMAIL        varchar2(100) COMMENT 'The email address of the customer.',
 PHONE        varchar2(20) COMMENT 'The phone number of the customer.',
 CREATED_DATE date COMMENT 'The date when the customer record was created.',
 LOAD_DTS     timestamp_ntz(9) NOT NULL,
